pay = operation({
  label: "pay supplier hold",
  input: (raw) => paySchema.safeParse(raw),
  depends: { state: state.controller, clock },
  run({ state, clock }, ctx) {
    const parsed = ctx.input;
    if (!parsed.success) return reject("invalid_payment");
    const current = state.get();
    const order = current.orders[parsed.data.data.order_id];
    if (!order) return reject("order_not_found", 404);
    if (!order.payment_status.awaiting_payment && !order.payment_status.paid_at)
      return reject("order_expired", 409);
    if (!order.payment_status.awaiting_payment) return reject("order_not_awaiting_payment", 409);
    if (parsed.data.data.payment.amount !== order.total_amount) return reject("incorrect_amount");
    state.set({
      ...current,
      orders: {
        ...current.orders,
        [order.id]: {
          ...order,
          payment_status: {
            ...order.payment_status,
            awaiting_payment: false,
            paid_at: new Date(clock.currentTimeMillis()).toISOString(),
          },
        },
      },
    });
    return reply(201, {
      data: {
        id: `pay_${ctx.random.uuid()}`,
        order_id: order.id,
        amount: order.total_amount,
        currency: "USD",
      },
    });
  },
})

intentKey = operation({
  label: "retain payment reply for key",
  input: z.object({
    key: z.string(),
    fingerprint: z.string(),
    response: z
      .object({
        status: z.number(),
        body: z.unknown(),
        headers: z.record(z.string(), z.string()).optional(),
      })
      .optional(),
  }),
  depends: { state: state.controller, inFlight },
  async run({ state, inFlight }, ctx): Promise<Wire.Reply | undefined> {
    const { key, fingerprint, response } = ctx.input;
    if (response) {
      state.update((current) => ({
        ...current,
        keys: { ...current.keys, [key]: { fingerprint, reply: structuredClone(response) } },
      }));
      inFlight.get(key)!.resolve(response);
      inFlight.delete(key);
      return;
    }
    const previous = state.get().keys[key];
    if (previous)
      return previous.fingerprint === fingerprint
        ? { ...previous.reply, headers: { "Idempotent-Replayed": "true" } }
        : rejectPayment("idempotency_key_in_use", 400, "idempotency_error");
    const pending = inFlight.get(key);
    if (pending)
      return pending.fingerprint === fingerprint
        ? { ...(await pending.response), headers: { "Idempotent-Replayed": "true" } }
        : rejectPayment("idempotency_key_in_use", 400, "idempotency_error");
    let resolve!: (reply: Wire.Reply) => void;
    const responsePromise = new Promise<Wire.Reply>((done) => {
      resolve = done;
    });
    inFlight.set(key, { fingerprint, response: responsePromise, resolve });
  },
})

